let html = $json.body || $json.data || $json.html || "";

// 1. Remove scripts, styles, metadata, and head section
html = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<meta[^>]*>/gi, '')
  .replace(/<head[\s\S]*?<\/head>/gi, '');

// 2. Convert list items to bullet text
html = html
  .replace(/<li[^>]*>/gi, '\n- ')
  .replace(/<\/li>/gi, '');

// 3. Convert paragraphs and breaks to new lines
html = html
  .replace(/<\/p>/gi, '\n')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/div>/gi, '\n');

// 4. Remove all remaining HTML tags
html = html.replace(/<[^>]+>/g, ' ');

// 5. Remove page numbers
html = html
  .replace(/Page \d+ of \d+/gi, '')
  .replace(/\bPage\s*\d+\b/gi, '')
  .replace(/^\s*\d+\s*$/gm, '');

// 6. Remove common header and footer text
html = html
  .replace(/©.*\n/gi, '')
  .replace(/All rights reserved.*/gi, '');

// 7. Decode HTML entities
html = html
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&#8212;/g, '—')
  .replace(/&#8211;/g, '–')
  .replace(/&#8226;/g, '•')
  .replace(/&#(\d+);/g, (match, code) => {
    return String.fromCodePoint(Number(code));
  })
  .replace(/&#x([0-9a-f]+);/gi, (match, code) => {
    return String.fromCodePoint(parseInt(code, 16));
  });

// 8. Normalize whitespace and line breaks
html = html
  .replace(/\r/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n\s*\n+/g, '\n\n')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n[ \t]+/g, '\n')
  .trim();

// 9. Return cleaned text
return [
  {
    json: {
      clean_text: html
    }
  }
];

// 1. Ambil teks mentah dari Gemini
const rawText = $json.text;

// 2. Temukan objek JSON dalam output AI
const jsonMatch = rawText.match(/\{[\s\S]*\}/);

// 3. Cek jika JSON ditemukan
if (!jsonMatch) {
  throw new Error("Tidak dapat menemukan JSON dalam output AI.");
}

// 4. Ambil string JSON
const jsonString = jsonMatch[0];

// 5. Parse string menjadi objek JSON
try {
  const jsonData = JSON.parse(jsonString);

  return [
    {
      json: jsonData
    }
  ];
} catch (error) {
  throw new Error("Gagal mem-parsing JSON: " + error.message);
}

// Ambil data JSON dari node sebelumnya
const data = $json;

// Helper function untuk mengolah array
const safeArray = (x) =>
  Array.isArray(x) && x.length > 0 ? x.join(", ") : "-";

const cat = data.category || {};

// Buat pesan Telegram
const msg = `
📌 *Keyword IT*
${safeArray(data.it_keywords)}

🎓 *Keyword Mengajar*
${safeArray(data.teaching_keywords)}

📂 *Kategori*
DevOps: ${safeArray(cat.devops)}
Backend: ${safeArray(cat.backend)}
Frontend: ${safeArray(cat.frontend)}
Cybersecurity: ${safeArray(cat.cybersecurity || cat.security)}
Cloud: ${safeArray(cat.cloud)}
Networking: ${safeArray(cat.networking)}

⭐ *Skor Teknis IT:* ${data.it_difficulty_score ?? "-"} / 10
⭐ *Skor Mengajar:* ${data.teaching_score ?? "-"} / 10

📝 *Ringkasan:*
${data.summary || "-"}
`;

return [{
  json: {
    telegram_text: msg.trim()
  }
}];
